cat > server/services/api-token-service.ts <<'EOF'
/**
 * Personal API tokens for scripts and CI. The secret is returned once from
 * `createApiToken`; only its hash is stored.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken, hasRoleAtLeast
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { hasRoleAtLeast } from "@/types/member";
import { envelope, memberResource, orgResource, requireFound } from "./_support";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const MAX_USABLE_TOKENS = 5;
const PREFIX_LENGTH = 12;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  if (parsed.scope === "write" && !hasRoleAtLeast(actor.role, "member")) {
    // Reuses the matrix entry for the `member` rank.
    assertCan(actor, "issue:create", orgResource(actor.orgId));
  }

  const token = `tfk_${randomToken(32)}`;
  const now = new Date();
  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      orgId: actor.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS,
  );
  if (apiToken === null) {
    throw new Error(
      `You can have at most ${MAX_USABLE_TOKENS} active API tokens per organization`,
    );
  }

  await emit("api_token.created", {
    ...envelope(actor.orgId, actor.userId),
    tokenId: apiToken.id,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  const target = userId ?? actor.userId;
  if (target !== actor.userId) {
    assertCan(actor, "member:invite", orgResource(orgId));
  }
  return apiTokenRepo.listApiTokens(orgId, target);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);
  const existing = requireFound(
    await apiTokenRepo.findApiToken(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    assertCan(actor, "member:invite", orgResource(orgId));
  }
  if (existing.revokedAt !== null) return existing;

  const revoked = await apiTokenRepo.markApiTokenRevoked(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );
  // Lost a race with another revoke: already revoked, nothing new to record.
  if (revoked === null) {
    return requireFound(
      await apiTokenRepo.findApiToken(orgId, tokenId),
      "ApiToken",
      tokenId,
    );
  }

  await emit("api_token.revoked", {
    ...envelope(orgId, actor.userId),
    tokenId,
    userId: revoked.userId,
  });
  return revoked;
}

export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const stored = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (stored === null || stored.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (now >= stored.expiresAt) return null;

  const org = await orgRepo.findOrgById(stored.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(stored.orgId, stored.userId);
  if (member === null || member.status !== "active") return null;

  await apiTokenRepo.markApiTokenUsed(stored.id, now);
  return {
    userId: stored.userId,
    orgId: stored.orgId,
    role: stored.scope === "read" ? "viewer" : member.role,
  };
}

/** Revokes a removed member's outstanding tokens, attributed to the remover. */
export function registerApiTokenListeners(): Unsubscribe {
  const off = subscribe("member.removed", async (payload) => {
    const tokens = await apiTokenRepo.listApiTokens(payload.orgId, payload.userId);
    for (const token of tokens) {
      if (token.revokedAt !== null) continue;
      const revoked = await apiTokenRepo.markApiTokenRevoked(
        payload.orgId,
        token.id,
        toIsoTimestamp(new Date()),
      );
      if (revoked === null) continue;
      await emit("api_token.revoked", {
        ...envelope(payload.orgId, payload.actorId),
        tokenId: token.id,
        userId: payload.userId,
      });
    }
  });
  return off;
}
EOF
